\set ON_ERROR_STOP on
CREATE SCHEMA sl_sim AUTHORIZATION postgres;
CREATE SCHEMA sl_sim_basic1_hosted_poc AUTHORIZATION postgres;
CREATE SCHEMA sl_sim_basic1_postpilot AUTHORIZATION sl_postpilot_owner;
CREATE SCHEMA supabase_migrations AUTHORIZATION postgres;
SET ROLE bootstrap;
CREATE TYPE public.friend_status AS ENUM ('pending','accepted','blocked');
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),display_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.friendships(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.profiles(id),friend_id uuid NOT NULL REFERENCES public.profiles(id),status public.friend_status NOT NULL,UNIQUE(user_id,friend_id),CHECK(user_id<>friend_id));
CREATE TABLE public.daily_trials(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trial_date date NOT NULL UNIQUE,seed bigint NOT NULL,reward_xp integer NOT NULL CHECK(reward_xp>=0));
CREATE TABLE public.trial_attempts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trial_id bigint NOT NULL REFERENCES public.daily_trials(id),user_id uuid NOT NULL REFERENCES public.profiles(id),completion integer NOT NULL CHECK(completion BETWEEN 0 AND 100));
CREATE TABLE public.reward_ledger(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,attempt_id bigint NOT NULL UNIQUE REFERENCES public.trial_attempts(id),xp integer NOT NULL CHECK(xp>=0));
CREATE VIEW public.accepted_friendships WITH(security_invoker=true) AS SELECT user_id,friend_id FROM public.friendships WHERE status='accepted';
CREATE FUNCTION public.friend_count(p_user uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY INVOKER AS $$SELECT count(*) FROM public.friendships WHERE user_id=p_user AND status='accepted'$$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['profiles','friendships','daily_trials','trial_attempts','reward_ledger'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',n);
END LOOP;END$$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY friendships_read ON public.friendships FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY trials_read ON public.daily_trials FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY attempts_read ON public.trial_attempts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY rewards_read ON public.reward_ledger FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.trial_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid()));
GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT SELECT ON public.daily_trials TO anon;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT SELECT ON TABLES TO authenticated;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['games','class_sessions','rooms','role_seats','network_tests','role_sessions','events','deliveries','control_state','branch_state','turn_states','control_snapshots'] LOOP
 EXECUTE format('CREATE TABLE sl_sim.%I(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,owner_id uuid NOT NULL REFERENCES auth.users(id),payload jsonb NOT NULL DEFAULT ''{}'',created_at timestamptz NOT NULL DEFAULT now())',n);
 EXECUTE format('ALTER TABLE sl_sim.%I ENABLE ROW LEVEL SECURITY',n);
 EXECUTE format('ALTER TABLE sl_sim.%I FORCE ROW LEVEL SECURITY',n);
 EXECUTE format('CREATE POLICY own_read ON sl_sim.%I FOR SELECT TO authenticated USING(owner_id=auth.uid())',n);
 EXECUTE format('GRANT SELECT ON sl_sim.%I TO authenticated',n);
 EXECUTE format('GRANT ALL ON sl_sim.%I TO service_role',n);
END LOOP;END$$;
GRANT USAGE ON SCHEMA sl_sim TO authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA sl_sim GRANT SELECT ON TABLES TO authenticated;
CREATE TABLE sl_sim_basic1_hosted_poc.sessions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,owner_id uuid NOT NULL REFERENCES auth.users(id));
CREATE TABLE sl_sim_basic1_hosted_poc.teams(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,session_id bigint NOT NULL REFERENCES sl_sim_basic1_hosted_poc.sessions(id),name text NOT NULL);
CREATE TABLE sl_sim_basic1_hosted_poc.turns(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,team_id bigint NOT NULL REFERENCES sl_sim_basic1_hosted_poc.teams(id),turn_no integer NOT NULL CHECK(turn_no BETWEEN 0 AND 10),cash numeric(12,2) NOT NULL);
CREATE TABLE supabase_migrations.schema_migrations(version text PRIMARY KEY,statements text[],name text);
RESET ROLE;
SET ROLE sl_postpilot_owner;
CREATE TABLE sl_sim_basic1_postpilot.sessions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,owner_id uuid NOT NULL);
CREATE TABLE sl_sim_basic1_postpilot.teams(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,session_id bigint NOT NULL REFERENCES sl_sim_basic1_postpilot.sessions(id));
CREATE TABLE sl_sim_basic1_postpilot.turns(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,team_id bigint NOT NULL REFERENCES sl_sim_basic1_postpilot.teams(id),turn_no integer NOT NULL CHECK(turn_no BETWEEN 0 AND 10),cash numeric(12,2) NOT NULL);
CREATE TABLE sl_sim_basic1_postpilot.events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,session_id bigint NOT NULL REFERENCES sl_sim_basic1_postpilot.sessions(id),payload jsonb NOT NULL DEFAULT '{}');
ALTER TABLE sl_sim_basic1_postpilot.sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON sl_sim_basic1_postpilot.sessions FOR SELECT TO authenticated USING(owner_id=auth.uid());
ALTER DEFAULT PRIVILEGES IN SCHEMA sl_sim_basic1_postpilot REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
RESET ROLE;
GRANT USAGE ON SCHEMA sl_sim_basic1_postpilot TO postgres,authenticated;
GRANT SELECT ON ALL TABLES IN SCHEMA sl_sim_basic1_postpilot TO postgres;
GRANT SELECT ON ALL SEQUENCES IN SCHEMA sl_sim_basic1_postpilot TO postgres;
GRANT SELECT ON sl_sim_basic1_postpilot.sessions TO authenticated;
DO $$DECLARE r record;BEGIN FOR r IN SELECT n.nspname,c.relname,c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','sl_sim','sl_sim_basic1_hosted_poc','supabase_migrations') AND c.relkind IN ('r','v') LOOP EXECUTE format('ALTER TABLE %I.%I OWNER TO postgres',r.nspname,r.relname);END LOOP;END$$;
ALTER FUNCTION public.friend_count(uuid) OWNER TO postgres;
ALTER TYPE public.friend_status OWNER TO postgres;
